```java
import java.util.Arrays;

/*
 * Template Method pattern for sorting algorithms.
 * Run:  javac SortingDemo.java && java SortingDemo
 * (Or split each class into its own file.)
 */

/**
 * Abstract template class. It fixes the contract every sorting
 * algorithm in this family must follow:
 *
 *   sort(array)      – the template method (the algorithm's skeleton);
 *   compare(a, b)    – the abstract step used to decide order;
 *   swap(arr, i, j)  – the abstract step used to reorder elements.
 *
 * A subclass provides its concrete algorithm as the skeleton of sort(),
 * but may only touch the data through the two abstract steps,
 * so compare() and swap() are the only hooks.
 */
public abstract class SortAlgorithm<T extends Comparable<T>> {

    /** Template method: the skeleton of the sorting algorithm. */
    public abstract void sort(T[] array);

    /** Abstract step: compare two elements (sign of a - b). */
    protected abstract int compare(T a, T b);

    /** Abstract step: exchange two positions. */
    protected abstract void swap(T[] array, int i, int j);
}

/** Concrete algorithm: Bubble Sort. */
class BubbleSort<T extends Comparable<T>> extends SortAlgorithm<T> {

    @Override
    public void sort(T[] array) {
        int n = array.length;
        for (int i = 0; i < n - 1; i++) {          // one pass per largest element
            boolean swapped = false;
            for (int j = 0; j < n - 1 - i; j++) {  // bubble the larger one right
                if (compare(array[j], array[j + 1]) > 0) {
                    swap(array, j, j + 1);
                    swapped = true;
                }
            }
            if (!swapped) return;                  // already in order
        }
    }

    @Override
    protected int compare(T a, T b) {
        return a.compareTo(b);
    }

    @Override
    protected void swap(T[] array, int i, int j) {
        T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

/** Concrete algorithm: Selection Sort. */
