import java.util.Arrays;

/**
 * Template Method pattern for sorting.
 *
 * SortAlgorithm is the abstract "template" class. It fixes the contract
 * that every sorting algorithm in this family must follow:
 *
 *   sort(array)  -- the entry point (template method)
 *     the algorithm's loop is implemented by the subclass, but all
 *     contact with the data must go through two abstract steps:
 *       compare(a, b)  -- decide the relative order of two elements
 *       swap(a, i, j)  -- exchange two elements
 *
 * Subclasses plug in a concrete algorithm (bubble, selection, ...).
 */
public abstract class SortAlgorithm<T extends Comparable<T>> {

    /**
     * Template method: the skeleton of the sorting algorithm.
     * Subclasses provide the concrete algorithm-specific loop;
     * they must only use compare() and swap() to read and move elements.
     */
    public abstract void sort(T[] array);

    /** Abstract step: compare two elements (Comparable contract: <0, 0, >0). */
    protected abstract int compare(T a, T b);

    /** Abstract step: swap two elements in the array. */
    protected abstract void swap(T[] array, int i, int j);

    /* -- convenience utilities (not part of the template contract) -- */

    protected void print(String label, T[] array) { ... }
}
